msg.payload = {
    status: 'healthy',
    service: 'VoiceFlow Pro',
    version: '1.0.0',
    timestamp: new Date().toISOString()
};
return msg;

const body = msg.payload;

if (!body.text || body.text.trim().length === 0) {
    msg.statusCode = 400;
    msg.payload = { error: 'Text is required' };
    return [null, msg];
}

const id = Date.now().toString(36) + Math.random().toString(36).substr(2, 9);

msg.conversion = {
    id: id,
    text: body.text,
    voice: body.voice || 'Roger',
    provider: (body.settings && body.settings.provider) || 'elevenlabs',
    stability: (body.settings && body.settings.stability) || 0.5,
    similarity_boost: (body.settings && body.settings.similarity_boost) || 0.75,
    metadata: body.metadata || {},
    callback_url: body.callback_url || null,
    status: 'queued',
    created_at: new Date().toISOString(),
    char_count: body.text.length,
    word_count: body.text.split(/\s+/).length
};

let conversions = flow.get('conversions') || [];
conversions.unshift(msg.conversion);
flow.set('conversions', conversions);

let stats = flow.get('stats') || { total: 0, successful: 0, failed: 0, minutes_used: 0 };
stats.total += 1;
flow.set('stats', stats);

msg.payload = {
    id: id,
    status: 'queued',
    message: 'Conversion queued successfully',
    estimated_time: Math.ceil(body.text.length / 500) + 's'
};

return [msg, null];

let conversions = flow.get('conversions') || [];
const idx = conversions.findIndex(c => c.id === msg.conversion.id);
if (idx >= 0) {
    conversions[idx].status = 'processing';
    flow.set('conversions', conversions);
}
return msg;

