const apiKey = global.get('GOOGLE_TTS_API_KEY');

msg.url = 'https://texttospeech.googleapis.com/v1/text:synthesize?key=' + apiKey;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    input: { text: msg.conversion.text },
