// This is a placeholder showing the request structure.
const region = global.get('AWS_REGION') || 'us-east-1';

msg.url = 'https://polly.' + region + '.amazonaws.com/v1/speech';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    OutputFormat: 'mp3',
