    VoiceId: 'Matthew',
    Engine: 'neural'
};

return msg;

const fs = require('fs');
const path = require('path');

const audioDir = '/data/audio-output';
try { fs.mkdirSync(audioDir, { recursive: true }); } catch(e) {}

const filename = msg.conversion.id + '.mp3';
const filepath = path.join(audioDir, filename);

try {
    let audioData;
    if (msg.conversion.provider === 'google' && msg.payload && msg.payload.audioContent) {
        audioData = Buffer.from(msg.payload.audioContent, 'base64');
    } else if (Buffer.isBuffer(msg.payload)) {
        audioData = msg.payload;
    } else {
        throw new Error('No audio data received from provider');
    }

    fs.writeFileSync(filepath, audioData);
    const fstats = fs.statSync(filepath);
    const durationEstimate = Math.ceil(msg.conversion.word_count / 2.5);

    let conversions = flow.get('conversions') || [];
    const idx = conversions.findIndex(c => c.id === msg.conversion.id);
    if (idx >= 0) {
        conversions[idx].status = 'completed';
        conversions[idx].completed_at = new Date().toISOString();
        conversions[idx].file_path = filepath;
        conversions[idx].file_url = '/audio/' + filename;
        conversions[idx].file_size = fstats.size;
        conversions[idx].duration_seconds = durationEstimate;
        flow.set('conversions', conversions);
    }

    let stats = flow.get('stats') || { total: 0, successful: 0, failed: 0, minutes_used: 0 };
    stats.successful += 1;
    stats.minutes_used += durationEstimate / 60;
    flow.set('stats', stats);

    msg.payload = {
        id: msg.conversion.id,
        status: 'completed',
        file_url: '/audio/' + filename,
        duration_seconds: durationEstimate,
        file_size: fstats.size
    };
    return [msg, null];
} catch (err) {
    let conversions = flow.get('conversions') || [];
    const idx = conversions.findIndex(c => c.id === msg.conversion.id);
    if (idx >= 0) {
        conversions[idx].status = 'failed';
        conversions[idx].error = err.message;
        flow.set('conversions', conversions);
    }

    let stats = flow.get('stats') || { total: 0, successful: 0, failed: 0, minutes_used: 0 };
    stats.failed += 1;
    flow.set('stats', stats);

    msg.payload = { id: msg.conversion.id, status: 'failed', error: err.message };
    return [null, msg];
}

if (msg.conversion && msg.conversion.callback_url) {
    msg.url = msg.conversion.callback_url;
    msg.method = 'POST';
    msg.headers = { 'Content-Type': 'application/json' };
    return msg;
}
return null;

const fs = require('fs');
const path = require('path');

const filename = msg.req.params.filename;
const filepath = path.join('/data/audio-output', filename);

if (fs.existsSync(filepath)) {
    msg.payload = fs.readFileSync(filepath);
    msg.headers = {
        'Content-Type': 'audio/mpeg',
        'Content-Disposition': 'inline; filename="' + filename + '"',
        'Cache-Control': 'public, max-age=86400'
    };
    msg.statusCode = 200;
} else {
    msg.payload = { error: 'Audio file not found' };
    msg.headers = { 'Content-Type': 'application/json' };
    msg.statusCode = 404;
}
return msg;

const stats = flow.get('stats') || { total: 0, successful: 0, failed: 0, minutes_used: 0 };
const conversions = flow.get('conversions') || [];
const quota = 60;

const successRate = stats.total > 0 ? Math.round((stats.successful / stats.total) * 100) : 0;

msg.payload = {
    conversions_this_month: stats.total,
    minutes_used: Math.round(stats.minutes_used * 10) / 10,
    minutes_quota: quota,
    success_rate: successRate,
    quota_usage: Math.round((stats.minutes_used / quota) * 100),
    recent_conversions: conversions.slice(0, 5)
};
return msg;

const conversions = flow.get('conversions') || [];
const q = msg.req.query;

let filtered = conversions;

if (q.status && q.status !== 'all') {
    filtered = filtered.filter(c => c.status === q.status);
}
if (q.search) {
    const s = q.search.toLowerCase();
    filtered = filtered.filter(c =>
        (c.text && c.text.toLowerCase().includes(s)) ||
        (c.voice && c.voice.toLowerCase().includes(s)) ||
        (c.id && c.id.toLowerCase().includes(s))
    );
}

const page = parseInt(q.page) || 1;
const limit = parseInt(q.limit) || 20;
const start = (page - 1) * limit;

msg.payload = {
    conversions: filtered.slice(start, start + limit),
    total: filtered.length,
    page: page,
    pages: Math.ceil(filtered.length / limit)
};
return msg;

const conversions = flow.get('conversions') || [];
const conv = conversions.find(c => c.id === msg.req.params.id);

if (conv) {
    msg.payload = conv;
    msg.statusCode = 200;
} else {
    msg.payload = { error: 'Conversion not found' };
    msg.statusCode = 404;
}
return msg;

const cached = global.get('voiceLibrary');
if (cached && cached.length > 0) {
    // apply filters to cached voices
    let voices = cached;
    const search = (msg.req.query.search || '').toLowerCase();
    const providerFilter = msg.req.query.provider || '';
    const genderFilter = msg.req.query.gender || '';
    if (search) voices = voices.filter(v => v.name.toLowerCase().includes(search) || (v.description||'').toLowerCase().includes(search));
    if (providerFilter && providerFilter !== 'all') voices = voices.filter(v => (v.provider||'').toLowerCase() === providerFilter.toLowerCase());
    if (genderFilter && genderFilter !== 'all') voices = voices.filter(v => v.gender === genderFilter);
    msg.payload = { voices, total: voices.length, provider: 'elevenlabs' };
    msg.statusCode = 200;
    return msg;
}

