// Adjust endpoint to match your Octopus API
msg.url = octUrl + '/stories';
if (msg.req.query.search) {
    msg.url += '?search=' + encodeURIComponent(msg.req.query.search);
}
if (msg.req.query.rundown) {
    msg.url += (msg.url.includes('?') ? '&' : '?') + 'rundown=' + encodeURIComponent(msg.req.query.rundown);
}

msg.method = 'GET';
msg.headers = {
    'Authorization': 'Bearer ' + octKey,
    'Accept': 'application/json'
};

return [msg, null];

// Adapt to your Octopus response format
const data = msg.payload;

let stories = [];
if (Array.isArray(data)) {
    stories = data;
} else if (data.stories) {
    stories = data.stories;
} else if (data.items) {
    stories = data.items;
} else if (data.results) {
    stories = data.results;
}

msg.payload = {
    stories: stories.map(s => ({
        id: s.id || s.storyId || '',
        title: s.title || s.headline || s.slug || 'Untitled',
        text: (s.body || s.content || s.text || '').substring(0, 200),
